import sys
MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    arr = data[1:]

    factors = [{} for _ in arr]
    primes = set()
    for i, value in enumerate(arr):
        x = value
        d = 2
        while d * d <= x:
            if x % d == 0:
                e = 0
                while x % d == 0:
                    x //= d
                    e += 1
                factors[i][d] = e
                primes.add(d)
            d += 1
        if x > 1:
            factors[i][x] = factors[i].get(x, 0) + 1
            primes.add(x)

    answer = 1
    for p in primes:
        # height is the current exponent relative to its minimum so far;
        # each DP value sums p^(sum of normalized exponents so far).
        dp = {0: 1}
        for j in range(n - 1):
            e = factors[j].get(p, 0)
            next_dp = {}
            prior_vertices = j + 1
            steps = (e, -e) if e else (0,)
            for height, ways in dp.items():
                for delta in steps:
                    raw = height + delta
                    if raw >= 0:
                        new_height = raw
                        added = new_height
                    else:
                        new_height = 0
                        # The new minimum is lower by -raw, shifting every
                        # preceding vertex's normalized exponent upward.
                        added = (-raw) * prior_vertices
                    contribution = ways * pow(p, added, MOD) % MOD
                    next_dp[new_height] = (next_dp.get(new_height, 0) + contribution) % MOD
            dp = next_dp
        answer = answer * sum(dp.values()) % MOD

    print(answer)

if __name__ == '__main__':
    solve()

