from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # For each pair, store its smaller endpoint in the bucket for its
        # larger endpoint. Once the right endpoint reaches b, this pair
        # forbids all starts <= a.
        buckets = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            buckets[b].append((a, i))

        largest = second = 0
        largest_id = -1
        gain = [0] * len(conflictingPairs)
        valid_count = 0

        for right in range(1, n + 1):
            for a, idx in buckets[right]:
                if a > largest:
                    second = largest
                    largest, largest_id = a, idx
                elif a > second:
                    second = a

            # Valid starts are largest+1 through right.
            valid_count += right - largest

            # Removing the unique largest constraint changes the bound to
            # the second largest. Equal maxima correctly yield zero gain.
            if largest_id != -1:
                gain[largest_id] += largest - second

        return valid_count + max(gain)

