            buckets[b].append((a, i))
        top1 = top2 = 0
        id1 = -1
        gain = [0] * len(conflictingPairs)
        total = 0
        for r in range(1, n + 1):
            for a, idx in buckets[r]:
                if a > top1:
                    top2 = top1
                    top1, id1 = a, idx
                elif a > top2:
                    top2 = a
            total += r - top1
            if id1 >= 0:
                gain[id1] += top1 - top2
        return total + max(gain)

