import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:
        return
    it=iter(data)
    n=next(it); m=next(it); q=next(it)
    edges=[]
    for _ in range(m):
        a=next(it)-1; b=next(it)-1; c=next(it)
        edges.append((a,b,c))
    queries=[]
    deleted=[False]*m
    for _ in range(q):
        typ=next(it)
        if typ==1:
            e=next(it)-1
            queries.append((1,e))
            deleted[e]=True
        else:
            x=next(it)-1; y=next(it)-1
            queries.append((2,x,y))

    inf=10**30
    dist=[[inf]*n for _ in range(n)]
    for i in range(n):
        dist[i][i]=0
    for e,(a,b,c) in enumerate(edges):
        if not deleted[e]:
            dist[a][b]=dist[b][a]=c

    # APSP in the graph after all forward deletions.
    for k in range(n):
        dk=dist[k]
        for i in range(n):
            dik=dist[i][k]
            if dik==inf:
                continue
            row=dist[i]
            for j in range(n):
                candidate=dik+dk[j]
                if candidate<row[j]:
                    row[j]=candidate

    answers=[]
    for query in reversed(queries):
        if query[0]==2:
            value=dist[query[1]][query[2]]
            answers.append(-1 if value==inf else value)
        else:
            a,b,w=edges[query[1]]
            # Snapshot distances to the endpoints before adding this road.
            da=[dist[i][a] for i in range(n)]
            db=[dist[i][b] for i in range(n)]
            for i in range(n):
                row=dist[i]
                for j in range(i,n):
                    value=min(row[j], da[i]+w+db[j], db[i]+w+da[j])
                    if value<row[j]:
                        row[j]=value
                        dist[j][i]=value
    print('\n'.join(map(str,reversed(answers))))

if __name__ == '__main__':
    main()

