import sys, math

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, budget = next(it), next(it)
    processes = [(next(it), next(it), next(it), next(it)) for _ in range(n)]

    def minimum_cost(k, a, p, b, q):
        if k == 0:
            return 0
        g = math.gcd(a, b)
        best = 10**30
        # Enumerate the count of the less cost-efficient machine. Any full
        # equal-capacity bundle of it can be replaced by the other machine.
        if p * b <= q * a:
            for y in range(a // g):
                x = max(0, (k - y * b + a - 1) // a)
                best = min(best, x * p + y * q)
        else:
            for x in range(b // g):
                y = max(0, (k - x * a + b - 1) // b)
                best = min(best, x * p + y * q)
        return best

    def feasible(k):
        total = 0
        for a, p, b, q in processes:
            total += minimum_cost(k, a, p, b, q)
            if total > budget:
                return False
        return True

    lo, hi = 0, 100 * budget + 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

solve()

