from math import comb

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)

        # A number with c set bits takes one operation to become c,
        # followed by the operations needed to reduce c to 1.
        valid = [False] * (length + 1)
        for c in range(1, length + 1):
            x = c
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            valid[c] = steps + 1 <= k

        answer = 0
        ones_so_far = 0
        # At each 1-bit of n, count smaller numbers that first differ there.
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                for total_ones in range(1, length + 1):
                    if valid[total_ones]:
                        need = total_ones - ones_so_far
                        if 0 <= need <= remaining:
                            answer += comb(remaining, need)
                ones_so_far += 1

        return answer % mod

