class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        valid = [False] * (L + 1)
        for c in range(1, L + 1):
            x = c
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            valid[c] = steps + 1 <= k
        ans = 0
        prefix = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = L - i - 1
                for c in range(1, L + 1):
                    if valid[c]:
                        need = c - prefix
                        if 0 <= need <= rem:
                            ans += comb(rem, need)
                prefix += 1
        return ans % MOD

