import sys

def feasible(l, r, intervals, n):
    p=list(range(n+1))
    def find(x):
        while p[x]!=x:
            p[x]=p[p[x]]; x=p[x]
        return x
    for i in range(l,r+1):
        a,b=intervals[i]
        x,y=find(a),find(b)
        if x!=y: p[x]=y
    adj=[[] for _ in range(n+1)]
    indeg=[0]*(n+1)
    for i in range(l,r+1):
        a,b=intervals[i]
        u=find(a)
        for x in range(a+1,b):
            v=find(x)
            if u!=v:
                adj[u].append(v); indeg[v]+=1
    q=[i for i in range(1,n+1) if find(i)==i and indeg[i]==0]
    seen=0
    while q:
        u=q.pop(); seen+=1
        for v in adj[u]:
            indeg[v]-=1
            if indeg[v]==0:q.append(v)
    return seen==sum(1 for i in range(1,n+1) if find(i)==i)

