import math

N = int(sys.stdin.buffer.readline())

# Compute floor(cuberoot(N)) exactly.
lo, hi = 0, 1
while hi ** 3 <= N:
    hi *= 2
while lo + 1 < hi:
    mid = (lo + hi) // 2
    if mid ** 3 <= N:
        lo = mid
    else:
        hi = mid

# Let d = x-y. Then N = d(3y^2 + 3dy + d^2),
# so d divides N and d^3 < N for positive y.
for d in range(1, lo + 1):
    if N % d:
        continue
    q = N // d
    # Solve 3y^2 + 3dy + d^2 = q via its discriminant.
    disc = 12 * q - 3 * d * d
    if disc < 0:
        continue
    root = math.isqrt(disc)
    if root * root != disc:
        continue
    numerator = root - 3 * d
    if numerator > 0 and numerator % 6 == 0:
        y = numerator // 6
        print(y + d, y)
        break
else:
    print(-1)

