    if not data:return
    n,q=map(int,data[:2]); s=data[2].decode()
    ones=[]; twos=[]; sl=[]
    for i,c in enumerate(s):
        if c=='1': ones.append(i)
        elif c=='2': twos.append(i)
        else: sl.append(i)
