    for _ in range(q):
        L,R=map(int,data[at:at+2]);at+=2
        l=L-1;r=R-1
        oi=bisect_left(ones,l); ti=bisect_right(twos,r)
        has_slash=bisect_left(sl,l)<len(sl) and sl[bisect_left(sl,l)]<=r
        if not has_slash:
            out.append('0');continue
        lo=0; hi=min(bisect_right(ones,r)-oi, ti-bisect_left(twos,l))
        # Search maximum balanced pair count.
        while lo<hi:
            k=(lo+hi+1)//2
            p=ones[oi+k-1]
            z=twos[ti-k]
            si=bisect_left(sl,p+1)
            if si<len(sl) and sl[si]<z and sl[si]<=r:
                lo=k
            else:
                hi=k-1
        out.append(str(2*lo+1))
    sys.stdout.write('\n'.join(out))

