from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        cap = k
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(cap, fact[i - 1] * i)

        def ways(odds: int, evens: int, next_parity: int) -> int:
            length = odds + evens
            if length == 0:
                return 1
            first_slots = (length + 1) // 2
            second_slots = length // 2
            if next_parity == 1:
                if odds != first_slots or evens != second_slots:
                    return 0
            else:
                if evens != first_slots or odds != second_slots:
                    return 0
            return min(cap, fact[odds] * fact[evens])

        total_odds = (n + 1) // 2
        total_evens = n // 2
        total = 0
        for value in range(1, n + 1):
            odds = total_odds - (value % 2 == 1)
            evens = total_evens - (value % 2 == 0)
            total += ways(odds, evens, 2 if value % 2 else 1)
            if total >= k:
                break
        if total < k:
            return []

        remaining = set(range(1, n + 1))
        odds, evens = total_odds, total_evens
        previous_parity = 0
        result = []
        rank = k
        for _ in range(n):
            for value in sorted(remaining):
                parity = value % 2
                if previous_parity and parity == previous_parity:
                    continue
                next_odds = odds - (parity == 1)
                next_evens = evens - (parity == 0)
                count = ways(next_odds, next_evens, 2 if parity == 1 else 1)
                if rank > count:
                    rank -= count
                else:
                    result.append(value)
                    remaining.remove(value)
                    odds, evens = next_odds, next_evens
                    previous_parity = parity
                    break
            else:
                return []
        return result

