class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        cap = k
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(cap, fact[i-1] * i)
        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))
        def ways(o, e, nxt):
            length = o + e
            if length == 0:
                return 1
            first = (length + 1) // 2
            second = length // 2
            if nxt == 1:
                if o != first or e != second:
                    return 0
            else:
                if e != first or o != second:
                    return 0
            return min(cap, fact[o] * fact[e])
        total = 0
