class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [0] * n
        powers[0] = 1 % k
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        coeff = []
        for i in range(m):
            c = powers[i]
            if i != n - 1 - i:
                c += powers[n - 1 - i]
            coeff.append(c % k)

        # dp[i][r] indicates whether the suffix of variables can contribute residue r.
        dp = [None] * (m + 1)
        dp[m] = bytearray([1] + [0] * (k - 1))
        for i in range(m - 1, -1, -1):
            nxt = dp[i + 1]
            cur = bytearray(k)
            c = coeff[i]
            for r in range(k):
                if nxt[r]:
                    for d in range(10):
                        cur[(r + d * c) % k] = 1
            dp[i] = cur

        digits = []
        used = 0
        for i, c in enumerate(coeff):
            first_allowed = 1 if i == 0 else 0
            for d in range(9, first_allowed - 1, -1):
                need = (-(used + d * c)) % k
                if dp[i + 1][need]:
                    digits.append(str(d))
                    used = (used + d * c) % k
                    break

        left = ''.join(digits)
        return left + left[:n // 2][::-1]

