class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n=len(edges)+1
        adj=[[] for _ in range(n)]
        for u,v,w in edges:
            adj[u].append((v,w)); adj[v].append((u,w))
        parent=[-1]*n
        pw=[0]*n
        order=[0]
        for u in order:
            for v,w in adj[u]:
                if v!=parent[u]:
                    parent[v]=u; pw[v]=w; order.append(v)
        dp0=[0]*n; dp1=[0]*n
        for u in reversed(order):
            base=0; gains=[]
            for v,w in adj[u]:
                if parent[v]==u:
                    base+=dp0[v]
                    gains.append(w+dp1[v]-dp0[v])
            gains.sort(reverse=True)
            positive=[x for x in gains if x>0]
            dp0[u]=base+sum(positive[:k])
            dp1[u]=base+sum(positive[:max(0,k-1)])
        return dp0[0]

