class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = [part for part in p.split('*') if part]
        if not parts:
            return 0

        occurrences = []
        for part in parts:
            starts = []
            i = s.find(part)
            while i != -1:
                starts.append(i)
                i = s.find(part, i + 1)  # include overlapping occurrences
            if not starts:
                return -1
            occurrences.append(starts)

        best = len(s) + 1
        first_len = len(parts[0])
        for start in occurrences[0]:
            end = start + first_len
            for j in range(1, len(parts)):
                k = bisect_left(occurrences[j], end)
                if k == len(occurrences[j]):
                    break
                end = occurrences[j][k] + len(parts[j])
            else:
                best = min(best, end - start)

        return -1 if best == len(s) + 1 else best

