    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    dist = [None] * n
    answer = [0] * n
    for start in range(n):
        if dist[start] is not None:
            continue
        dist[start] = 0
        stack = [start]
        component = []
        consistent = True
        while stack:
            v = stack.pop()
            component.append(v)
            for w, z in graph[v]:
                candidate = dist[v] ^ z
                if dist[w] is None:
                    dist[w] = candidate
                    stack.append(w)
