        for v in component:
            value = dist[v]
            for bit in range(30):
                ones[bit] += (value >> bit) & 1
        base = 0
        for bit, count in enumerate(ones):
            if 2 * count > len(component):
                base |= 1 << bit
        for v in component:
            answer[v] = dist[v] ^ base

    print(*answer)

