from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Produce the DFS postorder and record each subtree's interval in it.
        order = []
        left = [0] * n
        right = [0] * n
        stack = [(0, False)]
        while stack:
            v, exiting = stack.pop()
            if exiting:
                order.append(s[v])
                right[v] = len(order) - 1
            else:
                left[v] = len(order)
                stack.append((v, True))
                for c in reversed(children[v]):
                    stack.append((c, False))

        # Manacher radii for odd- and even-length palindromes.
        m = len(order)
        odd = [0] * m
        l, r = 0, -1
        for i in range(m):
            k = 1 if i > r else min(odd[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < m and order[i - k] == order[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        even = [0] * m
        l, r = 0, -1
        for i in range(m):
            k = 0 if i > r else min(even[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < m and order[i - k - 1] == order[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        answer = [False] * n
        for v in range(n):
            a, b = left[v], right[v]
            length = b - a + 1
            if length % 2:
                center = (a + b) // 2
                answer[v] = odd[center] >= length // 2 + 1
            else:
                center = (a + b + 1) // 2
                answer[v] = even[center] >= length // 2
        return answer

