from typing import List

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def reachable(x: int) -> set[int]:
            digits = list(str(x))
            values = {x}
            for i in range(len(digits)):
                for j in range(i + 1, len(digits)):
                    swapped = digits.copy()
                    swapped[i], swapped[j] = swapped[j], swapped[i]
                    # int() permits a leading zero created by the swap.
                    values.add(int(''.join(swapped)))
            return values

        outcomes = [reachable(x) for x in nums]
        pairs = 0
        for i in range(len(nums)):
            for j in range(i):
                # The operation applies to either one integer, not both.
                if nums[i] in outcomes[j] or nums[j] in outcomes[i]:
                    pairs += 1
        return pairs

