from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0

        slopes = [0] * (4 * n)
        intercepts = [0] * (4 * n)
        used = [False] * (4 * n)

        def insert(m, b, node, lo, hi):
            if not used[node]:
                slopes[node] = m
                intercepts[node] = b
                used[node] = True
                return

            mid = (lo + hi) // 2
            current_m, current_b = slopes[node], intercepts[node]
            if m * mid + b > current_m * mid + current_b:
                slopes[node], intercepts[node] = m, b
                m, b = current_m, current_b

            if lo == hi:
                return
            if m * lo + b > slopes[node] * lo + intercepts[node]:
                insert(m, b, node * 2, lo, mid)
            elif m * hi + b > slopes[node] * hi + intercepts[node]:
                insert(m, b, node * 2 + 1, mid + 1, hi)

        def query(x, node, lo, hi):
            ans = slopes[node] * x + intercepts[node] if used[node] else 0
