class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        def feasible(k: int) -> bool:
            # Bit s is set iff sum s can be formed by selecting query values
            # affecting this position among the first k queries.
            possible = [1] * n
            for left, right, value in queries[:k]:
                shifted = value
                for i in range(left, right + 1):
                    possible[i] |= possible[i] << shifted
            return all((possible[i] >> nums[i]) & 1 for i in range(n))

        if all(value == 0 for value in nums):
            return 0
        if not feasible(len(queries)):
            return -1

        low, high = 0, len(queries)
        while low < high:
            mid = (low + high) // 2
            if feasible(mid):
                high = mid
            else:
                low = mid + 1
        return low

