class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10000
        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if is_prime[p]:
                for multiple in range(p * p, limit, p):
                    is_prime[multiple] = False

        if is_prime[n] or is_prime[m]:
            return -1

        places = []
        place = 1
        for _ in str(n):
            places.append(place)
            place *= 10

        inf = float("inf")
        dist = [inf] * limit
        dist[n] = n
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            for place in places:
                digit = (value // place) % 10
                if digit > 0:
                    nxt = value - place
                    if not is_prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))
                if digit < 9:
                    nxt = value + place
                    if not is_prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))

        return -1

