from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[k] = LCP(nums, nums[k:])
        z = [0] * n
        left = right = 0
        for k in range(1, n):
            if k <= right:
                z[k] = min(right - k + 1, z[k - left])
            while k + z[k] < n and nums[z[k]] == nums[k + z[k]]:
                z[k] += 1
            if k + z[k] - 1 > right:
                left, right = k, k + z[k] - 1

        answer = 0
        for i in range(1, n - 1):
            # First subarray is a prefix of the second.
            first_condition = z[i] >= i
            if first_condition:
                # The second subarray must have length at least i.
                answer += max(0, n - 2 * i)

            # For each possible second-subarray length d, its equality with
            # the beginning of the third subarray is a Z-match in nums[i:].
            suffix = nums[i:]
            m = len(suffix)
            zz = [0] * m
            left = right = 0
            for k in range(1, m):
                if k <= right:
                    zz[k] = min(right - k + 1, zz[k - left])
                while k + zz[k] < m and suffix[zz[k]] == suffix[k + zz[k]]:
                    zz[k] += 1
                if k + zz[k] - 1 > right:
                    left, right = k, k + zz[k] - 1

            # Keep the third subarray at least as long as the second.
            for d in range(1, m // 2 + 1):
                if zz[d] >= d and (not first_condition or d < i):
                    answer += 1

        return answer

