from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        inf = 10**9
        # dp[j] is the minimum number of target indices used to match
        # pattern[:j] among the source characters processed so far.
        dp = [inf] * (m + 1)
        dp[0] = 0
        targets = set(targetIndices)

        for i, ch in enumerate(source):
            cost = 1 if i in targets else 0
            # Descending order ensures this source character is used at most once.
            for j in range(m - 1, -1, -1):
                if ch == pattern[j] and dp[j] < inf:
                    dp[j + 1] = min(dp[j + 1], dp[j] + cost)

        # Keep an embedding using as few removable positions as possible;
        # every other target index can be removed.
        return len(targetIndices) - dp[m]

