class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Traverse reversed edges: from 0, this finds nodes that can reach 0.
        reverse_graph = [[] for _ in range(n)]
        for a, b, weight in edges:
            reverse_graph[b].append((a, weight))

        inf = float('inf')
        best = [inf] * n
        best[0] = 0
        heap = [(0, 0)]

        # best[v] is the smallest possible maximum edge weight on a path v -> 0.
        while heap:
            cost, node = heapq.heappop(heap)
            if cost != best[node]:
                continue
            for predecessor, weight in reverse_graph[node]:
                candidate = max(cost, weight)
                if candidate < best[predecessor]:
                    best[predecessor] = candidate
                    heapq.heappush(heap, (candidate, predecessor))

        answer = max(best)
        return -1 if answer == inf else int(answer)

