        # Every valid copy differs from original by the same integer offset.
        min_offset = max(bounds[i][0] - original[i] for i in range(len(original)))
        max_offset = min(bounds[i][1] - original[i] for i in range(len(original)))
        return max(0, max_offset - min_offset + 1)

